def is_subset_sum(set, n, sum):
    # Base case: if the sum is 0, then a subset is found
    if sum == 0:
        return True
    # If no elements are left or the sum becomes negative, return False
    if n == 0 or sum < 0:
        return False
    # If the last element is greater than the sum, ignore it
    if set[n - 1] > sum:
        return is_subset_sum(set, n - 1, sum)
    # Check if the subset can be formed by including or excluding the last element
    return is_subset_sum(set, n - 1, sum) or is_subset_sum(set, n - 1, sum - set[n - 1])
```
